/**
 * Parent/child rules for issues.
 *
 * A root sits at level 0. Placing an issue under itself or under anything
 * below it is a cycle; a placement whose deepest descendant would pass
 * `MAX_SUB_ISSUE_DEPTH` is too deep. Archived rows stay in the tree for both
 * checks — they still move with their parent — and drop out of roll-ups.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueRollup, IssueStatus } from "@/types/issue";

export type HierarchyProblem = "cycle" | "too_deep";

/** The shape the placement and roll-up walks need. `Issue` satisfies it. */
export interface HierarchyIssue {
  readonly id: string;
  readonly parentId: string | null;
  readonly status: IssueStatus;
  readonly archivedAt: string | null;
}

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: HierarchyProblem,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} would create a cycle in the issue hierarchy.`
        : `Issue ${issueId} would nest deeper than ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** Id that is never stored, so a not-yet-inserted issue has no subtree. */
const NEW_ISSUE_ID = "\0";

/**
 * Why `issueId` cannot be placed under `parentId`, or null when it can.
 * `parentId === null` makes the issue a root. Pass `issues` as the whole
 * project, archived rows included.
 */
export function parentPlacementProblem(
  issueId: string,
  parentId: string | null,
  issues: readonly HierarchyIssue[],
): HierarchyProblem | null {
  const children = childrenByParent(issues);
  const byId = new Map(issues.map((issue) => [issue.id, issue]));

  if (parentId !== null) {
    if (parentId === issueId || isStrictDescendant(issueId, parentId, children)) {
      return "cycle";
    }
  }

  const parentLevel = parentId === null ? -1 : ancestorLevel(parentId, byId);
  if (parentLevel === "cycle") return "cycle";

  const relative = deepestRelativeDepth(issueId, children);
  if (parentLevel + 1 + relative > MAX_SUB_ISSUE_DEPTH) return "too_deep";
  return null;
}

/** Placement check for an issue that has not been inserted yet. */
export function newIssuePlacementProblem(
  parentId: string,
  issues: readonly HierarchyIssue[],
): HierarchyProblem | null {
  return parentPlacementProblem(NEW_ISSUE_ID, parentId, issues);
}

/** Ids of live issues strictly below `issueId`, archived intermediates included. */
export function liveDescendantIds(
  issueId: string,
  issues: readonly HierarchyIssue[],
): string[] {
  const children = childrenByParent(issues);
  const ids: string[] = [];
  eachDescendant(issueId, children, (node) => {
    if (node.archivedAt === null) ids.push(node.id);
  });
  return ids;
}

/** Open/closed/total over every non-archived issue strictly below `issueId`. */
export function rollupBelow(
  issueId: string,
  issues: readonly HierarchyIssue[],
): IssueRollup {
  const children = childrenByParent(issues);
  let open = 0;
  let closed = 0;
  eachDescendant(issueId, children, (node) => {
    if (node.archivedAt !== null) return;
    if (CLOSED_ISSUE_STATUSES.includes(node.status)) closed += 1;
    else open += 1;
  });
  return { total: open + closed, open, closed };
}

function childrenByParent(
  issues: readonly HierarchyIssue[],
): Map<string, HierarchyIssue[]> {
  const children = new Map<string, HierarchyIssue[]>();
  for (const issue of issues) {
    if (issue.parentId === null) continue;
    const bucket = children.get(issue.parentId);
    if (bucket === undefined) children.set(issue.parentId, [issue]);
    else bucket.push(issue);
  }
  return children;
}

function eachDescendant(
  rootId: string,
  children: ReadonlyMap<string, readonly HierarchyIssue[]>,
  visit: (node: HierarchyIssue) => void,
): void {
  const stack = [...(children.get(rootId) ?? [])];
  const seen = new Set<string>([rootId]);
  while (stack.length > 0) {
    const node = stack.pop();
    if (node === undefined || seen.has(node.id)) continue;
    seen.add(node.id);
    visit(node);
    const nested = children.get(node.id);
    if (nested !== undefined) {
      for (const child of nested) stack.push(child);
    }
  }
}

function isStrictDescendant(
  ancestorId: string,
  candidateId: string,
  children: ReadonlyMap<string, readonly HierarchyIssue[]>,
): boolean {
  let found = false;
  eachDescendant(ancestorId, children, (node) => {
    if (node.id === candidateId) found = true;
  });
  return found;
}

/** Levels above `id`, or `"cycle"` when the parent chain loops. */
function ancestorLevel(
  id: string,
  byId: ReadonlyMap<string, HierarchyIssue>,
): number | "cycle" {
  let level = 0;
  let current = byId.get(id);
  const seen = new Set<string>();
  while (current !== undefined) {
    if (seen.has(current.id)) return "cycle";
    seen.add(current.id);
    if (current.parentId === null) return level;
    const parent = byId.get(current.parentId);
    if (parent === undefined) return level;
    current = parent;
    level += 1;
  }
  return 0;
}

function deepestRelativeDepth(
  rootId: string,
  children: ReadonlyMap<string, readonly HierarchyIssue[]>,
): number {
  let max = 0;
  const stack: { id: string; depth: number }[] = [{ id: rootId, depth: 0 }];
  const seen = new Set<string>();
  while (stack.length > 0) {
    const item = stack.pop();
    if (item === undefined || seen.has(item.id)) continue;
    seen.add(item.id);
    if (item.depth > max) max = item.depth;
    for (const child of children.get(item.id) ?? []) {
      stack.push({ id: child.id, depth: item.depth + 1 });
    }
  }
  return max;
}

