/** Every issue in the project, archived rows included. No label hydration. */
export async function listProjectIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)))
    .all();
  return rows.map((row) => toIssue(row));
}

/**
 * Direct live children of `parentId`, oldest first. Creation time breaks ties
 * on the per-project issue number.
 */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function setIssueParentId(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

