  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const projectIssues = await issueRepo.listProjectIssues(orgId, issue.projectId);
  const ids: IssueId[] = [
    issue.id,
    ...(liveDescendantIds(issue.id, projectIssues) as IssueId[]),
  ];
  const archivedRows = await issueRepo.archiveLiveIssues(orgId, ids);
  const ordered = [...archivedRows].sort((left, right) => {
    if (left.id === issue.id) return -1;
    if (right.id === issue.id) return 1;
    if (left.createdAt < right.createdAt) return -1;
    if (left.createdAt > right.createdAt) return 1;
    return left.number - right.number;
  });
  const archived = ordered.find((row) => row.id === issue.id);
  if (archived === undefined) throw new Error(`Issue ${issueId} not found`);

  for (const row of ordered) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  return archived;
}

/**
 * Places `issueId` under `parentId`, or makes it a root when `parentId` is
 * null. Descendants keep their parent and move with it. A refused placement
 * writes nothing and announces nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (issue.parentId === input.parentId) return issue;

  await assertParentPlacement(
    input.orgId,
    issue.projectId,
    issue.id,
    input.parentId,
    issue.id,
  );

  const updated = await issueRepo.setIssueParentId(
    input.orgId,
    issue.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: updated.id,
    projectId: updated.projectId,
    changedFields: ["parentId"],
  });

  return updated;
}

