function isOpenStatus(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

function isClosingStatusChange(from: IssueStatus, to: IssueStatus): boolean {
  return isOpenStatus(from) && !isOpenStatus(to);
}

/**
 * The direct parent's assignee hears once when this closing leaves them with
 * no open issue below, at any depth. Preferences and the actor exclusion live
 * in `notify`. An archived parent, a parent with no assignee, and a parent
 * that still has open work stay silent.
 */
async function notifyParentIfSubIssuesCompleted(
  orgId: OrgId,
  issueId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null || issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (parent === null || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const projectIssues = await issueRepo.listProjectIssues(orgId, parent.projectId);
  if (rollupBelow(parent.id, projectIssues).open > 0) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every sub-issue under "${parent.title}" is complete`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

registerFanOut();

