import { setIssueParentSchema } from "@/schemas/issue";
import { updateNotificationPreferenceSchema } from "@/schemas/notification";
import { getDb, issues } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hier", "growth");
  other = await createTenant("hier-other", "growth");
});

afterAll(() => {
  cleanup();
});

function input(
  title: string,
  extras: { parentId?: IssueId | null; assigneeId?: UserId | null; status?: Issue["status"] } = {},
) {
  return {
    ...issueInput(tenant.org.id, tenant.project.id, { title }),
    ...extras,
  };
}

async function make(
  title: string,
  extras: { parentId?: IssueId | null; assigneeId?: UserId | null; status?: Issue["status"] } = {},
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, input(title, extras));
}

async function notices(recipientId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

describe("issue hierarchy", () => {
  it("maps hierarchy errors and accepts the new preference kind", () => {
    const error = new IssueHierarchyError("iss", "cycle");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error).code).toBe("conflict");
    expect(toAppError(new IssueHierarchyError("iss", "too_deep")).meta).toMatchObject({
      reason: "too_deep",
    });
    expect(
      updateNotificationPreferenceSchema.safeParse({
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        kind: "sub_issues_completed",
        inApp: true,
        email: true,
        digestOnly: false,
      }).success,
    ).toBe(true);
    expect(
      setIssueParentSchema.safeParse({
        orgId: tenant.org.id,
        issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
        parentId: null,
      }).success,
    ).toBe(true);
  });

  it("creates under a parent, lists oldest first, and rolls up", async () => {
    const root = await make("root", { assigneeId: tenant.userIds.admin });
    const older = await make("older", { parentId: root.id, status: "todo" });
    const younger = await make("younger", { parentId: root.id, status: "done" });
    const grand = await make("grand", { parentId: older.id, status: "canceled" });
    const buried = await make("buried", { parentId: grand.id, status: "in_progress" });

    const listed = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      root.id,
    );
    expect(listed.map((issue) => issue.id)).toEqual([older.id, younger.id]);

    expect(
      await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, root.id),
    ).toEqual({ total: 4, open: 2, closed: 2 });

    expect(
      await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, buried.id),
    ).toEqual({ total: 0, open: 0, closed: 0 });

    await issueRepo.archiveIssue(tenant.org.id, buried.id);
    expect(
      await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, root.id),
    ).toEqual({ total: 3, open: 1, closed: 2 });

    const still = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      grand.id,
    );
    expect(still).toEqual([]);
  });

  it("refuses a fifth level, a cycle, another project, and an archived parent", async () => {
    const a = await make("A");
    const b = await make("B", { parentId: a.id });
    const c = await make("C", { parentId: b.id });
    const d = await make("D", { parentId: c.id });

    const created: string[] = [];
    const off = subscribe("issue.created", () => {
      created.push("x");
    });
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });
    await expect(make("E", { parentId: d.id })).rejects.toBeInstanceOf(IssueHierarchyError);
    await expect(make("E", { parentId: d.id })).rejects.toMatchObject({ reason: "too_deep" });
    expect(created).toEqual([]);
    expect(
      await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).toBe(before);
    off();

    const rootParent = a.parentId;
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        parentId: d.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle", issueId: a.id });
    expect((await issueRepo.findIssueById(tenant.org.id, a.id))?.parentId).toBe(rootParent);
    expect((await issueRepo.findIssueById(tenant.org.id, b.id))?.parentId).toBe(a.id);

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: d.id,
        parentId: d.id,
      }),
    ).rejects.toMatchObject({ reason: "cycle" });

    const otherProject = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Other",
      slug: "other-proj",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      {
        ...issueInput(tenant.org.id, otherProject.id, { title: "foreign" }),
      },
    );
    await expect(make("cross", { parentId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: d.id,
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueRepo.findIssueById(tenant.org.id, d.id))?.parentId).toBe(c.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, foreign.id);
    await expect(make("under-archived", { parentId: foreign.id })).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: foreign.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.setIssueParent(other.actors.member, {
        orgId: tenant.org.id,
        issueId: a.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.listSubIssues(other.actors.owner, tenant.org.id, a.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, other.project.id as IssueId),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: a.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("moves a subtree without exceeding depth and announces parentId", async () => {
    const root = await make("move-root");
    const child = await make("move-child", { parentId: root.id });
    const grand = await make("move-grand", { parentId: child.id });
    const otherRoot = await make("move-other");

    const received: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => {
      received.push(payload);
    });
    const moved = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: root.id,
      parentId: otherRoot.id,
    });
    off();

    expect(moved.parentId).toBe(otherRoot.id);
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.parentId).toBe(root.id);
    expect((await issueRepo.findIssueById(tenant.org.id, grand.id))?.parentId).toBe(child.id);
    expect(received).toHaveLength(1);
    expect(received[0]).toMatchObject({
      issueId: root.id,
      changedFields: ["parentId"],
    });

    const again = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: root.id,
      parentId: otherRoot.id,
    });
    expect(again.parentId).toBe(otherRoot.id);

    const deep = await make("move-deep", { parentId: grand.id });
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: otherRoot.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.parentId).toBe(root.id);
    expect((await issueRepo.findIssueById(tenant.org.id, deep.id))?.parentId).toBe(grand.id);

    const lifted = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: deep.id,
      parentId: null,
    });
    expect(lifted.parentId).toBeNull();
  });

  it("archives live descendants once and leaves archived rows alone", async () => {
    const root = await make("arch-root");
    const live = await make("arch-live", { parentId: root.id });
    const already = await make("arch-already", { parentId: root.id });
    const under = await make("arch-under", { parentId: already.id });
    await issueRepo.archiveIssue(tenant.org.id, already.id);
    getDb()
      .update(issues)
      .set({ archivedAt: "2020-01-01T00:00:00.000Z" })
      .where(eq(issues.id, already.id))
      .run();

    const received: string[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload.issueId);
    });
    const archived = await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      root.id,
    );
    off();

    expect(archived.archivedAt).not.toBeNull();
    expect(received[0]).toBe(root.id);
    expect(received.sort()).toEqual([root.id, live.id, under.id].sort());
    const kept = await issueRepo.findIssueById(tenant.org.id, already.id);
    expect(kept?.archivedAt).toBe("2020-01-01T00:00:00.000Z");
    expect((await issueRepo.findIssueById(tenant.org.id, under.id))?.archivedAt).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, live.id))?.archivedAt).not.toBeNull();
  });

  it("tells the parent assignee once when the last open sub-issue closes", async () => {
    const parent = await make("note-parent", { assigneeId: tenant.userIds.admin });
    const child = await make("note-child", { parentId: parent.id });
    const sibling = await make("note-sibling", { parentId: parent.id, status: "done" });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "in_review",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "canceled",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "todo",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(1);

    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
