    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "sub_issues_completed",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(0);

