      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "sub_issues_completed",
      inApp: true,
      email: true,
      digestOnly: false,
    });

    const bare = await make("bare-parent");
    const bareChild = await make("bare-child", { parentId: bare.id });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: bareChild.id,
      status: "canceled",
    });
    expect(await notices(tenant.userIds.admin)).toHaveLength(0);

    const archivedParent = await make("arch-parent", { assigneeId: tenant.userIds.viewer });
    const archivedChild = await make("arch-child", { parentId: archivedParent.id });
    await issueRepo.archiveIssue(tenant.org.id, archivedParent.id);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: archivedChild.id,
      status: "done",
    });
    expect(await notices(tenant.userIds.viewer)).toHaveLength(0);
  });

  it("notifies only the direct parent", async () => {
    const grand = await make("gp", { assigneeId: tenant.userIds.admin });
    const mid = await make("mid", {
      parentId: grand.id,
      assigneeId: tenant.userIds.member,
      status: "done",
    });
    const leaf = await make("leaf", { parentId: mid.id });

    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: leaf.id,
      status: "done",
    });

    expect(await notices(tenant.userIds.member)).toHaveLength(1);
    expect(await notices(tenant.userIds.admin)).toHaveLength(0);
  });

  it("counts an archived descendant toward depth", async () => {
    const a = await make("depth-a");
    const b = await make("depth-b", { parentId: a.id });
    const c = await make("depth-c", { parentId: b.id });
    const d = await make("depth-d", { parentId: c.id });
    await issueRepo.archiveIssue(tenant.org.id, d.id);
    const other = await make("depth-other");
    const holder = await make("depth-holder", { parentId: other.id });

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: b.id,
        parentId: holder.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
  });
});

